                    'margin': 0,
                    'padding': 0
                });
                uploadLabel.css({
                    position: 'relative',
                    overflow: 'hidden',
                    cursor: 'default'
                });
                fileInput.css({
                    position: 'absolute',
                    'cursor': 'pointer',
                    'top': '0px',
                    'width': '100%',
                    'height': '100%',
                    'left': '0px',
                    'z-index': '100',
                    'opacity': '0.0',
                    'filter': 'alpha(opacity=0)',
                    '-ms-filter': "alpha(opacity=0)",
                    '-khtml-opacity': '0.0',
                    '-moz-opacity': '0.0'
                });
                form.appendTo(uploadLabel);

            } else {
                form.appendTo($('body'));
                form.css({
                    margin: 0,
                    padding: 0,
                    display: 'block',
                    position: 'absolute',
                    left: '-250px'
                });
                if(navigator.appVersion.indexOf("MSIE ") != -1)
                {
                    uploadLabel.attr('for', fileUploadId);
                } else {
                    uploadLabel.click(function () {
                        fileInput.click();
                    });
                }
            }
        }

function createHook (meta) {
  async function resolve (specifier, context, parentResolve) {
    const { parentURL = '' } = context
    const newSpecifier = deleteIitm(specifier)
    if (isWin && parentURL.indexOf('file:node') === 0) {
      context.parentURL = ''
    }
    const url = await parentResolve(newSpecifier, context, parentResolve)
    if (parentURL === '' && !EXTENSION_RE.test(url.url)) {
      entrypoint = url.url
      return { url: url.url, format: 'commonjs' }
    }

    if (isIitm(parentURL, meta) || hasIitm(parentURL)) {
      return url
    }

    if (context.importAssertions && context.importAssertions.type === 'json') {
      return url
    }


    specifiers.set(url.url, specifier)

    return {
      url: addIitm(url.url),
      shortCircuit: true,
      format: url.format
    }
  }

  const iitmURL = new URL('lib/register.js', meta.url).toString()
  async function getSource (url, context, parentGetSource) {
    if (hasIitm(url)) {
      const realUrl = deleteIitm(url)
      const exportNames = await getExports(realUrl, context, parentGetSource)
      return {
        source: `
import { register } from '${iitmURL}'
import * as namespace from ${JSON.stringify(url)}
const set = {}
${exportNames.map((n) => `
let $${n} = namespace.${n}
export { $${n} as ${n} }
set.${n} = (v) => {
  $${n} = v
  return true
}
`).join('\n')}
register(${JSON.stringify(realUrl)}, namespace, set, ${JSON.stringify(specifiers.get(realUrl))})
`
      }
    }

    return parentGetSource(url, context, parentGetSource)
  }

  async function load (url, context, parentLoad) {
    if (hasIitm(url)) {
      const { source } = await getSource(url, context, parentLoad)
      return {
        source,
        shortCircuit: true,
        format: 'module'
      }
    }

    return parentLoad(url, context, parentLoad)
  }

  if (NODE_MAJOR >= 17 || (NODE_MAJOR === 16 && NODE_MINOR >= 12)) {
    return { load, resolve }
  } else {
    return {
      load,
      resolve,
      getSource,
      getFormat (url, context, parentGetFormat) {
        if (hasIitm(url)) {
          return {
            format: 'module'
          }
        }
        if (url === entrypoint) {
          return {
            format: 'commonjs'
          }
        }

        return parentGetFormat(url, context, parentGetFormat)
      }
    }
  }
}

function uploadFile(ev) {
        var form, data, dialog, filename;
        ev.preventDefault();
        form = $("#upload-form");
        filename = form.find('input[name="file"]').val();
        console.log("Filename: "+filename);
        if (filename === "") {
            alert("No file selected");
            return;
        }
        form.find('input[name="ajax"]').val("1");
        data = new FormData(form[0]);
        $("#upload-form .submit").prop("disabled", true);
        dialog = $('#dialog-box')
        dialog.find(".modal-body").html('<p>Uploading ' +
                                        encodeURIComponent(filename) +
                                        '</p><div class="error"></div>');
        showDialog();
        $.ajax({
            url: form.attr("action"),
            data: data,
            type: "POST",
            enctype: 'multipart/form-data',
            processData: false,
            contentType: false,
            timeout: 600000,
            cache: false
        }).done(function (data) {
            var err, htm;

            $("#btnSubmit").prop("disabled", false);
            if(data.error) {
                err = dialog.find('.modal-body .error');
                err.text(data.error);
                return;
            }
            dialog.find(".modal-body").html('<p>Finished uploading ' +
                                            encodeURIComponent(filename) +
                                            '<span class="bool-yes ">&check;</span>');
            if(data.upload_url) {
                $('#upload-form').attr('action', data.upload_url);
            }
            if(data.csrf_token) {
                $('#upload-form input[name="csrf_token"]').val(data.csrf);
            }
            if(data.file_html){
                $('#'+data.name).remove();
                htm = $(data.file_html);
                htm.insertBefore('#media-files .error-row');
                htm.find('.delete-file').click(deleteFile);
                htm.find('.btn-index').click(indexFile);
                window.setTimeout(closeDialog, 500);
            }
        }).fail(function (e) {
            var err = dialog.find('.modal-body .error');
            if (e.responseJSON) {
                err.text(e.responseJSON.error);
            }
            else if (e.statusText) {
                err.text(e.status + ' ' + e.statusText);
            } else if (e.responseText) {
                err.text(e.responseText);
            } else {
                err.text(JSON.stringify(e));
            }
            console.error(e);
        }).always(function() {
            $("#upload-form .submit").prop("disabled", false);
        });
        return false;
    }

function path2short(path) {
    if (path.length < pathLimit) return path;
    const soft = `${prefix2parentfolder(fullpath2pathname(path)) + pathHellip}/${fullpath2filename(path)}`;
    if (soft.length < pathLimit && soft.length > 2) return soft;
    const hard = `${path.substring(0, path.indexOf('/') + 1) + pathHellip}/${fullpath2filename(path)}`;
    return hard.length < pathLimit ? htmlEscape(hard) : htmlEscape(path.substring(0, pathLimit) + pathHellip);
}

function appendElement(el,domBuilder,currentNSMap){
	var tagName = el.tagName;
	var localNSMap = null;
	var i = el.length;
	while(i--){
		var a = el[i];
		var qName = a.qName;
		var value = a.value;
		var nsp = qName.indexOf(':');
		if(nsp>0){
			var prefix = a.prefix = qName.slice(0,nsp);
			var localName = qName.slice(nsp+1);
			var nsPrefix = prefix === 'xmlns' && localName
		}else{
			localName = qName;
			prefix = null
			nsPrefix = qName === 'xmlns' && ''
		}
		a.localName = localName ;
		if(nsPrefix !== false){
			if(localNSMap == null){
				localNSMap = {}
				_copy(currentNSMap,currentNSMap={})
			}
			currentNSMap[nsPrefix] = localNSMap[nsPrefix] = value;
			a.uri = NAMESPACE.XMLNS
			domBuilder.startPrefixMapping(nsPrefix, value)
		}
	}
	var i = el.length;
	while(i--){
		a = el[i];
		var prefix = a.prefix;
		if(prefix){
			if(prefix === 'xml'){
				a.uri = NAMESPACE.XML;
			}if(prefix !== 'xmlns'){
				a.uri = currentNSMap[prefix || '']

			}
		}
	}
	var nsp = tagName.indexOf(':');
	if(nsp>0){
		prefix = el.prefix = tagName.slice(0,nsp);
		localName = el.localName = tagName.slice(nsp+1);
	}else{
		prefix = null;
		localName = el.localName = tagName;
	}
	var ns = el.uri = currentNSMap[prefix || ''];
	domBuilder.startElement(ns,localName,tagName,el);
	if(el.closed){
		domBuilder.endElement(ns,localName,tagName);
		if(localNSMap){
			for (prefix in localNSMap) {
				if (Object.prototype.hasOwnProperty.call(localNSMap, prefix)) {
					domBuilder.endPrefixMapping(prefix);
				}
			}
		}
	}else{
		el.currentNSMap = currentNSMap;
		el.localNSMap = localNSMap;
		return true;
	}
}

function KanbanService(
    $q,
    $window,
    gettextCatalog,
    SharedPropertiesService,
    RestErrorService,
    FilterTrackerReportService
) {
    const headers = {
        "content-type": "application/json",
        "X-Client-UUID": SharedPropertiesService.getUUID(),
    };

    return {
        getArchive,
        getBacklog,
        getItems,
        getArchiveSize,
        getBacklogSize,
        getColumnContentSize,
        collapseColumn,
        expandColumn,
        reorderColumn,
        reorderBacklog,
        reorderArchive,
        expandBacklog,
        collapseBacklog,
        expandArchive,
        collapseArchive,
        moveInBacklog,
        moveInArchive,
        moveInColumn,
        updateKanbanLabel,
        deleteKanban,
        addColumn,
        reorderColumns,
        removeColumn,
        editColumn,
        updateKanbanName,
        removeKanban,
        updateSelectableReports,
    };

    function getAnyColumnItems(url, params) {
        return $q.when(
            get(encodeURI(url), { params }).then((response) => {
                const total = response.headers.get("X-PAGINATION-SIZE");
                return response.json().then((items) => {
                    return { results: augmentItems(items.collection), total };
                });
            })
        );
    }

    function getAnyColumnSize(url, params) {
        return $q.when(
            head(encodeURI(url), { params }).then((response) => {
                return Number.parseInt(response.headers.get("X-PAGINATION-SIZE"), 10);
            })
        );
    }

    function getBacklog(kanban_id, limit, offset) {
        let query_params = { limit, offset };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnItems(`/api/v1/kanban/${kanban_id}/backlog`, query_params);
    }

    function getArchive(kanban_id, limit, offset) {
        let query_params = { limit, offset };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnItems(`/api/v1/kanban/${kanban_id}/archive`, query_params);
    }

    function getItems(kanban_id, column_id, limit, offset) {
        let query_params = { column_id, limit, offset };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnItems(`/api/v1/kanban/${kanban_id}/items`, query_params);
    }

    function getBacklogSize(kanban_id) {
        let query_params = {};
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnSize(`/api/v1/kanban/${kanban_id}/backlog`, query_params);
    }

    function getArchiveSize(kanban_id) {
        let query_params = {};
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnSize(`/api/v1/kanban/${kanban_id}/archive`, query_params);
    }

    function getColumnContentSize(kanban_id, column_id) {
        let query_params = { column_id };
        augmentQueryParamsWithFilterTrackerReport(query_params);
        return getAnyColumnSize(`/api/v1/kanban/${kanban_id}/items`, query_params);
    }

    function augmentItems(collection) {
        var is_collapsed = SharedPropertiesService.doesUserPrefersCompactCards();
        collection.forEach(function (item) {
            item.is_collapsed = is_collapsed;
        });

        return collection;
    }

    function reorderAnyColumn(url, dropped_item_id, compared_to) {
        return $q.when(
            patch(encodeURI(url), {
                headers,
                body: JSON.stringify({
                    order: getOrderArgumentsFromComparedTo(dropped_item_id, compared_to),
                }),
            }).catch(catchRestError)
        );
    }

    function reorderColumn(kanban_id, column_id, dropped_item_id, compared_to) {
        return reorderAnyColumn(
            `/api/v1/kanban/${kanban_id}/items?column_id=${column_id}`,
            dropped_item_id,
            compared_to
        );
    }

    function reorderBacklog(kanban_id, dropped_item_id, compared_to) {
        return reorderAnyColumn(
            `/api/v1/kanban/${kanban_id}/backlog`,
            dropped_item_id,
            compared_to
        );
    }

    function reorderArchive(kanban_id, dropped_item_id, compared_to) {
        return reorderAnyColumn(
            `/api/v1/kanban/${kanban_id}/archive`,
            dropped_item_id,
            compared_to
        );
    }

    function moveInAnyColumn(url, dropped_item_id, compared_to, from_column) {
        const patch_arguments = {
            add: {
                ids: [dropped_item_id],
            },
            from_column: from_column,
        };
        if (compared_to) {
            patch_arguments.order = getOrderArgumentsFromComparedTo(dropped_item_id, compared_to);
        }

        return $q.when(
            patch(encodeURI(url), {
                headers,
                body: JSON.stringify(patch_arguments),
            }).catch(catchRestError)
        );
    }

    function moveInBacklog(kanban_id, dropped_item_id, compared_to, from_column) {
        return moveInAnyColumn(
            `/api/v1/kanban/${kanban_id}/backlog`,
            dropped_item_id,
            compared_to,
            from_column
        );
    }

    function moveInArchive(kanban_id, dropped_item_id, compared_to, from_column) {
        return moveInAnyColumn(
            `/api/v1/kanban/${kanban_id}/archive`,
            dropped_item_id,
            compared_to,
            from_column
        );
    }

    function moveInColumn(kanban_id, column_id, dropped_item_id, compared_to, from_column) {
        return moveInAnyColumn(
            `/api/v1/kanban/${kanban_id}/items?column_id=${column_id}`,
            dropped_item_id,
            compared_to,
            from_column
        );
    }

    function getOrderArgumentsFromComparedTo(dropped_item_id, compared_to) {
        return {
            ids: [dropped_item_id],
            direction: compared_to.direction,
            compared_to: compared_to.item_id,
        };
    }

    function updateKanbanLabel(kanban_id, kanban_label) {
        return $q.when(
            patch(encodeURI(`/api/v1/kanban/${kanban_id}`), {
                headers,
                body: JSON.stringify({ label: kanban_label }),
            })
        );
