									cb2.style.background = 'transparent';
									cb2.setAttribute('title', mxResources.get(
										cb2.defaultChecked ?
										'removeIt' : 'add', [tag]));

									mxEvent.addListener(cb2, 'change', function(evt)
									{
										if (cb2.checked)
										{
